const crm = $('Notion - Đọc lead sau gom tin').first().json || {};

const latestMessage =
  $('Telegram - Nhận tin nhắn').first().json.message?.text ||
  $('Telegram - Nhận tin nhắn').first().json.message?.caption ||
  '';

const saleStageForSpam = String(
  crm.property_giai_o_n_sale ||
  crm.property_giai_doan_sale ||
  ''
).trim();

const isUnreachableFollowUp =
  saleStageForSpam === 'Không liên hệ được' &&
  /gọi|liên hệ|số điện thoại|sđt|nghe máy|chưa|rảnh|tiện/i.test(String(latestMessage || ''));

function normalizeText(input) {
  return String(input || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/[0-9]+$/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenSimilarity(a, b) {
  const aTokens = new Set(String(a || '').split(' ').filter(Boolean));
  const bTokens = new Set(String(b || '').split(' ').filter(Boolean));

  if (aTokens.size === 0 || bTokens.size === 0) return 0;

  let intersection = 0;
  for (const token of aTokens) {
    if (bTokens.has(token)) intersection++;
  }

  const union = new Set([...aTokens, ...bTokens]).size;
  return intersection / union;
}

function getValue(...keys) {
  for (const key of keys) {
    if (crm[key] !== undefined && crm[key] !== null && crm[key] !== '') {
      return crm[key];
    }
  }
  return '';
}

function looksLikePhone(text) {
  const raw = String(text || '').trim();
  const digitsOnly = raw.replace(/\D/g, '');

  return /^[\d\s\.\-\+]+$/.test(raw) && digitsOnly.length >= 5;
}

function hasMeaningfulWebsiteIntent(text) {
  const n = normalizeText(text);
  if (!n) return false;

  const meaningfulWords = [
    'web', 'website', 'landing', 'landingpage',
    'ban hang', 'gio hang', 'my pham', 'bat dong san',
    'doanh nghiep', 'cong ty', 'spa', 'nha hang',
    'khach san', 'du an', 'bao gia', 'thiet ke',
    'lap trinh', 'crm', 'erp', 'api', 'seo',
    'dat lich', 'thanh toan', 'van chuyen',
    'san pham', 'dich vu', 'tin tuc', 'blog'
  ];

  return meaningfulWords.some(word => n.includes(word));
}

function isLikelyGibberish(text) {
  const raw = String(text || '').trim();
  const normalized = normalizeText(raw);

  if (!normalized) return false;
  if (looksLikePhone(raw)) return false;
  if (hasMeaningfulWebsiteIntent(raw)) return false;

  const tokens = normalized.split(' ').filter(Boolean);

  const allowWords = [
    'web', 'website', 'landing', 'landingpage', 'crm', 'erp', 'api',
    'seo', 'app', 'wordpress', 'shopify', 'sapo', 'haravan',
    'ban', 'hang', 'gio', 'thanh', 'toan', 'van', 'chuyen',
    'doanh', 'nghiep', 'bat', 'dong', 'san', 'my', 'pham',
    'khach', 'nha', 'spa', 'du', 'an', 'bao', 'gia',
    'thiet', 'ke', 'lap', 'trinh', 'tich', 'hop', 'phan', 'quyen',
    'minh', 'can', 'muon', 'lam', 'cho', 'hoi', 'tu', 'van'
  ];

  const hasAllowedWord = tokens.some(token => allowWords.includes(token));
  if (hasAllowedWord) return false;

  // Một từ dài, không rõ nghĩa, ví dụ: daiurtwet, aeyertgdrfg
  if (tokens.length === 1 && tokens[0].length >= 6) {
    return true;
  }

  // Nhiều token nhưng hầu hết là chuỗi lạ dài
  const weirdTokens = tokens.filter(token => {
    if (token.length < 6) return false;
    if (allowWords.includes(token)) return false;
    return true;
  });

  if (tokens.length >= 2 && weirdTokens.length / tokens.length >= 0.6) {
    return true;
  }

  return false;
}

const normalizedMessage = normalizeText(latestMessage);

const storedNormalized = normalizeText(getValue(
  'property_tin_nh_n_chu_n_ho_cu_i',
  'property_tin_nh_n_chuan_hoa_cuoi',
  'property_tin_nh_chuan_hoa_cuoi'
));

const previousRepeatCount = Number(getValue(
  'property_s_l_n_l_p_g_n_gi_ng',
  'property_so_lan_lap_gan_giong',
  'property_s_l_n_l_p_g_n_gi_ng_'
) || 0);

const previousSpamCount = Number(getValue(
  'property_s_l_n_spam',
  'property_so_lan_spam'
) || 0);

const botAlreadyPaused =
  crm.property_bot_t_m_d_ng === true ||
  crm.property_bot_tam_dung === true;

const pendingText = String(crm.property_tin_nh_n_ch || '');
const pendingLines = pendingText
  .split('\n')
  .map(x => x.trim())
  .filter(Boolean);

const previousFromPending =
  pendingLines.length >= 2
    ? normalizeText(pendingLines[pendingLines.length - 2])
    : '';

const previousNormalized = storedNormalized || previousFromPending;

const isExactRepeat =
  previousNormalized &&
  normalizedMessage &&
  normalizedMessage === previousNormalized;

const isNearRepeat =
  previousNormalized &&
  normalizedMessage &&
  !isExactRepeat &&
  tokenSimilarity(previousNormalized, normalizedMessage) >= 0.82;

const repeatedChars = /(.)\1{5,}/.test(normalizedMessage);

const tooShortNonsense =
  normalizedMessage.length > 0 &&
  normalizedMessage.length <= 2 &&
  !looksLikePhone(latestMessage);

const badWords = [
  'dm', 'dmm', 'clm', 'dit', 'lon', 'cac', 'cc',
  'fuck', 'shit'
];

const hasBadWord = badWords.some(word =>
  normalizedMessage.split(' ').includes(word)
);

// Kiểm tra spam trong toàn bộ Tin nhắn chờ đã gom
const suspiciousPendingLines = pendingLines.filter(line => {
  const n = normalizeText(line);

  if (!n) return false;
  if (looksLikePhone(line)) return false;
  if (hasMeaningfulWebsiteIntent(line)) return false;

  return (
    isLikelyGibberish(line) ||
    /(.)\1{5,}/.test(n) ||
    badWords.some(word => n.split(' ').includes(word))
  );
});

const hasManyPendingMessages = pendingLines.length >= 3;
const hasManyGibberishMessages = suspiciousPendingLines.length >= 2;

const hasMeaningfulIntent = hasMeaningfulWebsiteIntent(latestMessage);

let repeatCount = (isExactRepeat || isNearRepeat)
  ? previousRepeatCount + 1
  : 0;

let spamCount = previousSpamCount;
let shouldSkipAI = false;
let pauseBot = botAlreadyPaused;
let spamReason = '';
let spamReply = '';

// ===============================
// LOGIC CHỐNG SPAM MỚI
// ===============================

if (isUnreachableFollowUp && !hasBadWord) {
  // Khách hỏi lại sau khi Sale không liên hệ được thì không tính spam
  repeatCount = 0;
  shouldSkipAI = false;
  pauseBot = botAlreadyPaused;
  spamReason = 'Không';
  spamReply = '';

} else if (botAlreadyPaused) {
  shouldSkipAI = true;
  pauseBot = true;
  spamReason = 'Bot đang tạm dừng do spam';
  spamReply =
    'Dạ cuộc trò chuyện này đang được tạm dừng xử lý tự động vì trước đó có nhiều tin nhắn không rõ nội dung. Nếu bạn cần tư vấn website thật, vui lòng nhắn lại một nội dung rõ ràng sau nhé.';

} else if (hasManyPendingMessages && hasManyGibberishMessages) {
  shouldSkipAI = true;
  pauseBot = true;
  spamCount += 1;
  repeatCount += 1;
  spamReason = 'Khách gửi nhiều tin nhắn vô nghĩa liên tiếp';
  spamReply =
    'Dạ mình tạm dừng xử lý tự động cuộc trò chuyện này vì có nhiều tin nhắn không rõ nội dung. Bên mình sẽ kiểm tra lại sau nhé.';

} else if (hasBadWord || repeatedChars || tooShortNonsense || isLikelyGibberish(latestMessage)) {
  shouldSkipAI = true;
  spamCount += 1;
  spamReason = hasBadWord
    ? 'Tin nhắn có nội dung không phù hợp'
    : 'Tin nhắn có dấu hiệu spam hoặc không rõ nội dung';

  if (spamCount >= 2) {
    pauseBot = true;
    spamReply =
      'Dạ mình tạm dừng xử lý tự động cuộc trò chuyện này vì có dấu hiệu spam. Bên mình sẽ kiểm tra lại sau nhé.';
  } else {
    pauseBot = false;
    spamReply =
      'Dạ bạn nhắn giúp mình nội dung rõ hơn về nhu cầu làm website để mình tư vấn chính xác nhé.';
  }

} else if ((isExactRepeat || isNearRepeat) && repeatCount <= 3) {
  // Lặp nhẹ 1-3 lần: KHÔNG chặn AI
  // Vì workflow đã có Wait + Trạm chốt chặn tin cuối, nên chỉ tin cuối được xử lý
  shouldSkipAI = false;
  pauseBot = false;
  spamReason = 'Tin nhắn lặp nhẹ nhưng vẫn cho AI xử lý';
  spamReply = '';

} else if ((isExactRepeat || isNearRepeat) && repeatCount >= 4 && repeatCount < 6) {
  // Lặp nhiều hơn: nhắc nhẹ, không tính spam, không tạm dừng
  shouldSkipAI = true;
  pauseBot = false;
  spamReason = 'Khách gửi lặp nhiều lần';
  spamReply =
    'Dạ mình đã nhận được nhiều tin nhắn giống nhau rồi. Bạn chờ mình xử lý thông tin để tránh bị trùng nhé.';

} else if ((isExactRepeat || isNearRepeat) && repeatCount >= 6) {
  // Lặp quá nhiều mới tính spam/tạm dừng
  shouldSkipAI = true;
  pauseBot = true;
  spamCount += 1;
  spamReason = 'Khách gửi lặp quá nhiều lần';
  spamReply =
    'Dạ mình đã nhận được nhiều tin nhắn giống nhau rồi. Mình tạm ghi nhận thông tin để tránh xử lý trùng nhé.';
}

// Không chặn số điện thoại lần đầu
if (looksLikePhone(latestMessage) && repeatCount === 0 && !hasBadWord) {
  shouldSkipAI = false;
  pauseBot = botAlreadyPaused;
  spamReason = 'Không';
  spamReply = '';
}

// Nếu nội dung có nhu cầu website rõ ràng và chỉ lặp nhẹ, ưu tiên cho AI xử lý
if (
  hasMeaningfulIntent &&
  (isExactRepeat || isNearRepeat) &&
  repeatCount <= 3 &&
  !hasBadWord &&
  !botAlreadyPaused
) {
  shouldSkipAI = false;
  pauseBot = false;
  spamReason = 'Tin nhắn lặp nhẹ nhưng có nhu cầu website rõ ràng';
  spamReply = '';
}

return [{
  json: {
    latest_message: latestMessage,
    normalized_message: normalizedMessage,
    previous_normalized: previousNormalized || '',
    pending_lines_count: pendingLines.length,
    suspicious_pending_lines_count: suspiciousPendingLines.length,
    repeat_count: repeatCount,
    spam_count: spamCount,
    should_skip_ai: shouldSkipAI,
    pause_bot: pauseBot,
    spam_reason: spamReason || 'Không',
    spam_reply: spamReply || ''
  }
}];

