let rawText =
  $input.first().json.text ||
  $input.first().json.output ||
  $input.first().json.response ||
  '';

let cleanText = String(rawText)
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// Phòng trường hợp LLM lỡ bọc thêm chữ ngoài JSON
let jsonMatch = cleanText.match(/\{[\s\S]*\}/);

if (jsonMatch) {
  cleanText = jsonMatch[0];
}

try {
  let parsedData = JSON.parse(cleanText);

  parsedData.customer_name = parsedData.customer_name || 'Chưa có';
  parsedData.phone_number = parsedData.phone_number || 'Chưa có';
  parsedData.need_summary = parsedData.need_summary || 'Chưa có';
  parsedData.customer_ai_note = parsedData.customer_ai_note || 'Chưa có';

  if (String(parsedData.customer_ai_note).length > 1800) {
    parsedData.customer_ai_note = String(parsedData.customer_ai_note).slice(-1800);
  }

  parsedData.reply_message =
    parsedData.reply_message ||
    'Dạ mình đã ghi nhận thông tin của bạn. Bạn cho mình biết thêm nhu cầu chính của website để mình tư vấn đúng hơn nhé.';

  parsedData.handoff_needed = parsedData.handoff_needed === true;
  parsedData.handoff_reason = parsedData.handoff_reason || 'Không cần';

  // ===============================
  // ĐỌC TIN NHẮN MỚI NHẤT
  // ===============================

  const latestCustomerMessage =
    $('Telegram - Nhận tin nhắn').first().json.message?.text ||
    $('Telegram - Nhận tin nhắn').first().json.message?.caption ||
    '';

  const cleanedLatestMessage = String(latestCustomerMessage).trim();

  // ===============================
  // ĐỌC TRẠNG THÁI CRM / SALE
  // ===============================

  const crmData = $('Notion - Đọc lead sau gom tin').first().json || {};

  const saleStage = String(
    crmData.property_giai_o_n_sale ||
    crmData.property_giai_doan_sale ||
    ''
  ).trim();

  const pauseReason = String(
    crmData.property_l_do_t_m_d_ng ||
    crmData.property_ly_do_tam_dung ||
    ''
  ).trim();

  const isSaleUnreachable =
    saleStage === 'Không liên hệ được' ||
    pauseReason.toLowerCase().includes('không liên hệ');

  let shouldNotifySale = false;

  // ===============================
  // HÀM LẤY SĐT VIỆT NAM TỪ CÂU NHẮN
  // Ví dụ: "số đúng của mình là 09XXXXXXXX ạ"
  // ===============================

  function extractValidVNPhoneFromText(text) {
    const rawText = String(text || '');

    const candidates =
      rawText.match(/(?:\+?84|0)[\s\.\-]*(?:3|5|7|8|9)(?:[\s\.\-]*\d){8}/g) || [];

    for (const candidate of candidates) {
      const normalizedPhone = String(candidate).replace(/[\s\.\-]/g, '');

      let phone = normalizedPhone;

      if (phone.startsWith('+84')) {
        phone = '0' + phone.slice(3);
      }

      if (phone.startsWith('84')) {
        phone = '0' + phone.slice(2);
      }

      const vnMobileRegex = /^0(3|5|7|8|9)\d{8}$/;

      const isFakeSequence =
        /12345678|1111111|0000000|9999999|2222222|3333333|4444444|5555555|6666666|7777777|8888888/.test(phone);

      if (vnMobileRegex.test(phone) && !isFakeSequence) {
        return phone;
      }
    }

    return '';
  }

  function normalizeValidVNPhone(value) {
    const raw = String(value || '').trim();

    // Lấy số và dấu +, bỏ chữ thừa như "ạ", "nha", "số mình là..."
    let phone = raw.replace(/[^\d+]/g, '');

    if (phone.startsWith('+84')) {
      phone = '0' + phone.slice(3);
    }

    if (phone.startsWith('84')) {
      phone = '0' + phone.slice(2);
    }

    const vnMobileRegex = /^0(3|5|7|8|9)\d{8}$/;

    const isFakeSequence =
      /12345678|1111111|0000000|9999999|2222222|3333333|4444444|5555555|6666666|7777777|8888888/.test(phone);

    if (vnMobileRegex.test(phone) && !isFakeSequence) {
      return phone;
    }

    return '';
  }

  const latestValidPhoneFromText = extractValidVNPhoneFromText(cleanedLatestMessage);

  // ===============================
  // PHÁT HIỆN KHÁCH ĐANG CỐ NHẬP SĐT
  // ===============================

  const looksLikePhoneAttempt =
    /^[\d\s\.\-\+]+$/.test(cleanedLatestMessage) &&
    cleanedLatestMessage.replace(/\D/g, '').length >= 5;

  const alreadyHasNeed =
    parsedData.need_summary &&
    parsedData.need_summary !== 'Chưa có';

  const alreadyHasName =
    parsedData.customer_name &&
    parsedData.customer_name !== 'Chưa có';

  const noValidPhoneYet =
    !parsedData.phone_number ||
    parsedData.phone_number === 'Chưa có' ||
    parsedData.phone_number === 'Chưa rõ';

  // Ưu tiên lấy SĐT hợp lệ trực tiếp từ tin nhắn mới nhất
  // để tránh AI trả về kèm chữ như "09XXXXXXXX ạ"
  if (latestValidPhoneFromText) {
    parsedData.phone_number = latestValidPhoneFromText;
  } else if (
    looksLikePhoneAttempt &&
    alreadyHasNeed &&
    noValidPhoneYet &&
    (alreadyHasName || isSaleUnreachable)
  ) {
    parsedData.phone_number = cleanedLatestMessage;
  }

  // ===============================
  // KIỂM TRA SỐ ĐIỆN THOẠI
  // ===============================

  parsedData.has_valid_phone = false;
  let invalidPhoneAttempt = false;

  if (
    parsedData.phone_number &&
    parsedData.phone_number !== 'Chưa có' &&
    parsedData.phone_number !== 'Chưa rõ'
  ) {
    const validPhone = normalizeValidVNPhone(parsedData.phone_number);

    if (validPhone) {
      parsedData.phone_number = validPhone;
      parsedData.has_valid_phone = true;
    } else {
      parsedData.phone_number = 'Chưa có';
      parsedData.has_valid_phone = false;
      invalidPhoneAttempt = true;
      shouldNotifySale = false;
      parsedData.handoff_needed = false;
      parsedData.handoff_reason = 'Không cần';
      parsedData.reply_message =
        'Dạ số điện thoại này có vẻ chưa đúng định dạng. Bạn kiểm tra lại giúp mình, SĐT thường gồm 10 số và bắt đầu bằng 03, 05, 07, 08 hoặc 09 nhé.';
    }
  }

  // ===============================
  // TRƯỜNG HỢP SALE KHÔNG LIÊN HỆ ĐƯỢC
  // ===============================

  if (isSaleUnreachable === true && invalidPhoneAttempt !== true) {
    parsedData.handoff_needed = true;
    parsedData.handoff_reason = 'Khách phản hồi sau khi Sale không liên hệ được';

    const latestTextForReply = String(cleanedLatestMessage || '');
    const latestValidPhone = extractValidVNPhoneFromText(latestTextForReply);
    const latestHasValidPhone = !!latestValidPhone;

    if (latestHasValidPhone) {
      parsedData.phone_number = latestValidPhone;
      parsedData.has_valid_phone = true;
    }

    const givesCallbackTime =
      /(\d{1,2}\s*h|\d{1,2}\s*giờ|hôm nay|ngày mai|chiều|sáng|tối|trưa|lúc|sau \d|trước \d|rảnh|tiện nghe|gọi lại lúc|gọi lại vào|liên hệ lại lúc|liên hệ lại vào)/i.test(latestTextForReply);

    if (latestHasValidPhone) {
      shouldNotifySale = true;
      parsedData.reply_message =
        'Dạ mình đã ghi nhận lại số điện thoại của bạn. Bên mình sẽ chuyển chuyên viên liên hệ lại để hỗ trợ chi tiết hơn nhé. Nếu sau khoảng 30 phút bạn chưa thấy bên mình liên hệ, bạn nhắn lại giúp mình để mình kiểm tra và hỗ trợ tiếp nhé.';

    } else if (parsedData.has_valid_phone === true && givesCallbackTime) {
      shouldNotifySale = true;
      parsedData.reply_message =
        'Dạ mình đã ghi nhận thời gian bạn tiện nghe máy. Bên mình sẽ chuyển chuyên viên liên hệ lại để hỗ trợ chi tiết hơn nhé. Nếu đến thời gian đó bạn chưa thấy bên mình liên hệ, bạn nhắn lại giúp mình để mình kiểm tra và hỗ trợ tiếp nhé.';

    } else {
      shouldNotifySale = false;

      if (parsedData.has_valid_phone === true) {
        parsedData.reply_message =
          'Dạ bên mình đã liên hệ nhưng chưa kết nối được với bạn. Bạn xác nhận lại giúp mình số điện thoại đang dùng hoặc cho mình biết thời gian tiện nghe máy để chuyên viên liên hệ lại nhé.';
      } else {
        parsedData.reply_message =
          'Dạ bên mình đã liên hệ nhưng chưa kết nối được với bạn. Bạn cho mình xin lại số điện thoại hoặc thời gian tiện nghe máy để chuyên viên bên mình liên hệ lại nhé.';
      }
    }

    if (
      parsedData.customer_ai_note &&
      parsedData.customer_ai_note !== 'Chưa có'
    ) {
      if (!String(parsedData.customer_ai_note).toLowerCase().includes('không liên hệ được')) {
        parsedData.customer_ai_note =
          `${parsedData.customer_ai_note} Sale từng không liên hệ được, khách đã phản hồi lại / cần liên hệ lại.`;
      }
    } else {
      parsedData.customer_ai_note =
        'Sale từng không liên hệ được, khách đã phản hồi lại / cần liên hệ lại.';
    }
  }

  // ===============================
  // XỬ LÝ KHÁCH CHỌN TÍNH NĂNG CƠ BẢN TRƯỚC
  // Không hiểu nhầm "trước" là deadline
  // ===============================

  const normalizedLatestForBasicChoice = cleanedLatestMessage
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .trim();

  const basicChoiceContext = String(
    parsedData.need_summary + ' ' +
    parsedData.customer_ai_note + ' ' +
    (crmData.property_nhu_c_u || '') + ' ' +
    (crmData.property_tin_nh_n_ch || '')
  )
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd');

  const customerChoseBasicOrderFirst =
    /dat hang co ban|tinh nang dat hang co ban|co ban truoc|truoc di|truoc da|co ban/i.test(normalizedLatestForBasicChoice) &&
    /ban hang|my pham|gio hang|san pham|shop|cua hang/i.test(basicChoiceContext);

  if (customerChoseBasicOrderFirst && isSaleUnreachable !== true) {
    parsedData.handoff_needed = false;
    parsedData.handoff_reason = 'Không cần';
    shouldNotifySale = false;

    if (/my pham/i.test(basicChoiceContext)) {
      parsedData.need_summary =
        'Website bán hàng mỹ phẩm có giỏ hàng và tính năng đặt hàng cơ bản';
    } else {
      parsedData.need_summary =
        'Website bán hàng có giỏ hàng và tính năng đặt hàng cơ bản';
    }

    parsedData.reply_message =
      'Dạ mình đã ghi nhận bạn muốn làm website bán hàng có giỏ hàng và tính năng đặt hàng cơ bản trước. Như vậy mình sẽ chưa ghi nhận thanh toán online hoặc quản lý đơn hàng nâng cao ở giai đoạn này. Bạn đã có tên thương hiệu/logo hoặc danh sách sản phẩm mẫu chưa ạ?';

    parsedData.customer_ai_note =
      'Khách cần website bán mỹ phẩm có giỏ hàng. Khách muốn dùng tính năng đặt hàng cơ bản trước, chưa chọn thanh toán online/quản lý đơn hàng nâng cao. Cần tư vấn thêm cấu trúc sản phẩm và quy trình đặt hàng cơ bản.';
  }

  // ===============================
  // CHỐT LOGIC CHUYỂN SALE BÌNH THƯỜNG
  // ===============================

  if (
    parsedData.handoff_needed === true &&
    parsedData.has_valid_phone !== true &&
    invalidPhoneAttempt !== true &&
    isSaleUnreachable !== true
  ) {
    const latestTextForReply = String(cleanedLatestMessage || '');

    const normalizedLatestForQuestion = latestTextForReply
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd');

    const isPriceQuestion =
      /bao gia|chi phi|ngan sach|gia chot|giam gia|bao nhieu tien|het bao nhieu|tam bao nhieu/i.test(normalizedLatestForQuestion) ||
      /(\d+)\s*(trieu|tr)\b/i.test(normalizedLatestForQuestion);

    const isTimeQuestion =
      /deadline|han chot|bao lau|may ngay|may tuan|thoi gian|khi nao xong|ngay ban giao|ban giao khi nao|cuoi thang|dau thang|truoc ngay|truoc thang|truoc \d{1,2}/i.test(normalizedLatestForQuestion);

    let ackMessage = 'Dạ mình đã ghi nhận thông tin của bạn.';
    let detailMessage = 'Phần này cần chuyên viên kiểm tra theo nhu cầu thực tế để tư vấn chính xác hơn.';

    if (isPriceQuestion && isTimeQuestion) {
      ackMessage = 'Dạ mình đã ghi nhận phần ngân sách và thời gian mong muốn của bạn.';
      detailMessage = 'Phần báo giá và thời gian triển khai cần chuyên viên kiểm tra theo tính năng thực tế để tư vấn chính xác hơn.';
    } else if (isPriceQuestion) {
      ackMessage = 'Dạ mình đã ghi nhận phần chi phí/ngân sách bạn đang quan tâm.';
      detailMessage = 'Phần báo giá cần chuyên viên kiểm tra theo loại website, giao diện và tính năng thực tế để tư vấn chính xác hơn.';
    } else if (isTimeQuestion) {
      ackMessage = 'Dạ mình đã ghi nhận thời gian mong muốn của bạn.';
      detailMessage = 'Thời gian triển khai cần chuyên viên kiểm tra theo khối lượng tính năng thực tế để tư vấn chính xác hơn.';
    }

    parsedData.reply_message =
      `${ackMessage} ${detailMessage} Bạn cho mình xin số điện thoại để bên mình liên hệ hỗ trợ chi tiết nhé.`;
  }

  if (
    parsedData.handoff_needed === true &&
    parsedData.has_valid_phone === true &&
    isSaleUnreachable !== true
  ) {
    shouldNotifySale = true;
    parsedData.reply_message =
      'Dạ mình đã ghi nhận nhu cầu của bạn và đã chuyển thông tin cho chuyên viên tư vấn. Bên mình sẽ liên hệ qua số điện thoại bạn đã cung cấp để hỗ trợ chi tiết hơn nhé. Nếu sau khoảng 30 phút bạn chưa thấy bên mình liên hệ, bạn nhắn lại giúp mình để mình kiểm tra và hỗ trợ tiếp nhé.';
  }

  if (parsedData.handoff_needed !== true) {
    parsedData.handoff_reason = 'Không cần';
    shouldNotifySale = false;
  }

  // ===============================
  // XỬ LÝ CÂU TRẢ LỜI MƠ HỒ KIỂU "CÓ Ạ"
  // Tránh tự hiểu khách cần tất cả tính năng
  // ===============================

  const normalizedLatestMessageForIntent = cleanedLatestMessage
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .trim();

  const latestIsOnlyVagueYes =
    /^(co|co a|da co|ok|duoc|uh|u|yes)$/i.test(normalizedLatestMessageForIntent);

  const summaryForVagueCheck = String(
    parsedData.need_summary + ' ' +
    parsedData.customer_ai_note + ' ' +
    parsedData.reply_message + ' ' +
    (crmData.property_nhu_c_u || '') + ' ' +
    (crmData.property_tin_nh_n_ch || '')
  )
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd');

  const vagueSalesWebsiteContext =
    /my pham|ban hang|gio hang|san pham|shop|cua hang/i.test(summaryForVagueCheck);

  const parsedThinksBothPaymentAndOrder =
    /thanh toan online|cong thanh toan|payment/i.test(summaryForVagueCheck) &&
    /quan ly don hang|don hang/i.test(summaryForVagueCheck);

  const customerClearlySaidBothInLatest =
    /ca hai|can ca hai|lam ca hai|tat ca|ca thanh toan.*quan ly/i.test(normalizedLatestMessageForIntent);

  if (
    latestIsOnlyVagueYes &&
    vagueSalesWebsiteContext &&
    parsedThinksBothPaymentAndOrder &&
    !customerClearlySaidBothInLatest &&
    !customerChoseBasicOrderFirst
  ) {
    parsedData.handoff_needed = false;
    parsedData.handoff_reason = 'Không cần';
    shouldNotifySale = false;
    parsedData.reply_message =
      'Dạ bạn muốn tích hợp cả thanh toán online và quản lý đơn hàng, hay chỉ cần một trong hai tính năng đó trước ạ?';
  }

  // ===============================
  // LÀM SẠCH + GIỮ GHI CHÚ KHÁCH / AI
  // Không để ghi chú cũ bị ghi đè bởi ghi chú quá chung chung
  // ===============================

  let cleanedAiNote = String(parsedData.customer_ai_note || '').trim();

  const existingAiNoteFromCrm = String(
    crmData.property_ghi_ch_kh_ch_ai ||
    crmData.property_ghi_chu_khach_ai ||
    ''
  ).trim();

  const allCustomerTextForNote = [
    crmData.property_nhu_c_u,
    existingAiNoteFromCrm,
    parsedData.need_summary,
    parsedData.customer_ai_note,
    crmData.property_tin_nh_n_ch,
    cleanedLatestMessage
  ]
    .filter(Boolean)
    .join('\n');

  const normalizedCustomerTextForNote = allCustomerTextForNote
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd');

  function normalizeNoteText(value) {
    return String(value || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd')
      .trim();
  }

  function isEmptyNote(note) {
    const n = normalizeNoteText(note);
    return (
      !n ||
      n === 'chua co' ||
      n === 'khong co' ||
      n === 'null' ||
      n === 'undefined'
    );
  }

  function isGenericNote(note) {
    const n = normalizeNoteText(note);

    if (isEmptyNote(note)) return true;

    return (
      n === 'khach can tu van website.' ||
      n === 'khach can tu van website' ||
      n === 'khach can sale ho tro.' ||
      n === 'khach can sale ho tro' ||
      n === 'khach can tu van them.' ||
      n === 'khach can tu van them' ||
      n.length < 35
    );
  }

  function noteContainsBadGuess(note) {
    return /do dự|do du|lưỡng lự|luong lu|phân vân|phan van|chưa chắc|chua chac|hoàn tư|hoan tu|muốn hoàn tư|muon hoan tu|đầy đủ thông tin|day du thong tin|đã cung cấp đầy đủ|da cung cap day du/i.test(
      String(note || '')
    );
  }

  const customerMentionedLater =
    /để sau|de sau|bổ sung sau|bo sung sau|cái đó để sau|cai do de sau/i.test(normalizedCustomerTextForNote);

  const contextIsBrandOrLogo =
    /tên thương hiệu|ten thuong hieu|thương hiệu|thuong hieu|logo|hình ảnh|hinh anh/i.test(normalizedCustomerTextForNote);

  const customerSaidVagueYesForNote =
    /^(co|co a|da co|ok|duoc|uh|u|yes)$/i.test(normalizedLatestMessageForIntent);

  const customerClearlySaidBoth =
    /cả hai|ca hai|cần cả hai|can ca hai|làm cả hai|lam ca hai|tất cả|tat ca|cả thanh toán.*quản lý|ca thanh toan.*quan ly/i.test(normalizedCustomerTextForNote);

  const customerClearlySaidPayment =
    /cần thanh toán online|can thanh toan online|thanh toán online|thanh toan online|cổng thanh toán|cong thanh toan|payment/i.test(normalizedCustomerTextForNote);

  const customerClearlySaidOrderManagement =
    /cần quản lý đơn hàng|can quan ly don hang|quản lý đơn hàng|quan ly don hang|theo dõi đơn hàng|theo doi don hang/i.test(normalizedCustomerTextForNote);

  const hasOnlinePayment =
    /thanh toán online|thanh toan online|payment|cổng thanh toán|cong thanh toan/i.test(normalizedCustomerTextForNote);

  const hasOrderManagement =
    /quản lý đơn hàng|quan ly don hang|đơn hàng|don hang/i.test(normalizedCustomerTextForNote);

  const hasCart =
    /giỏ hàng|gio hang|cart/i.test(normalizedCustomerTextForNote);

  const hasProductCatalog =
    /danh mục|danh muc|sản phẩm|san pham|trang chi tiết|trang chi tiet|chi tiết sản phẩm|chi tiet san pham/i.test(normalizedCustomerTextForNote);

  const hasBeautyWebsite =
    /mỹ phẩm|my pham/i.test(normalizedCustomerTextForNote);

  const hasRealEstateWebsite =
    /bất động sản|bat dong san/i.test(normalizedCustomerTextForNote);

  const hasLandingPage =
    /landing/i.test(normalizedCustomerTextForNote);

  const hasSalesWebsite =
    /bán hàng|ban hang|shop|cửa hàng|cua hang/i.test(normalizedCustomerTextForNote);

  function buildCleanNoteFromCustomerText() {
    const parts = [];

    if (hasBeautyWebsite) {
      parts.push('Khách cần website bán mỹ phẩm');
    } else if (hasRealEstateWebsite) {
      parts.push('Khách cần website bất động sản');
    } else if (hasLandingPage) {
      parts.push('Khách cần landing page');
    } else if (hasSalesWebsite) {
      parts.push('Khách cần website bán hàng');
    } else {
      parts.push('Khách cần tư vấn website');
    }

    const features = [];

    if (hasProductCatalog) {
      features.push('danh mục/trang chi tiết sản phẩm');
    }

    if (hasCart) {
      features.push('giỏ hàng');
    }

    // Chỉ ghi chắc chắn thanh toán online nếu khách nói rõ, hoặc nói rõ cần cả hai
    if (customerClearlySaidPayment || customerClearlySaidBoth) {
      features.push('thanh toán online');
    }

    // Chỉ ghi chắc chắn quản lý đơn hàng nếu khách nói rõ, hoặc nói rõ cần cả hai
    if (customerClearlySaidOrderManagement || customerClearlySaidBoth) {
      features.push('quản lý đơn hàng');
    }

    if (/dự án|du an/i.test(normalizedCustomerTextForNote)) {
      features.push('danh sách/giới thiệu dự án');
    }

    if (/bộ lọc|bo loc|lọc khu vực|loc khu vuc|khu vực|khu vuc/i.test(normalizedCustomerTextForNote)) {
      features.push('bộ lọc khu vực');
    }

    if (/form|liên hệ|lien he|tư vấn|tu van/i.test(normalizedCustomerTextForNote)) {
      features.push('form liên hệ/nhận tư vấn');
    }

    if (features.length > 0) {
      parts.push(`Chức năng đã nêu: ${features.join(', ')}`);
    }

    if (
      customerSaidVagueYesForNote &&
      (hasOnlinePayment || hasOrderManagement) &&
      !customerClearlySaidBoth &&
      !customerClearlySaidPayment &&
      !customerClearlySaidOrderManagement
    ) {
      parts.push('Khách đang quan tâm thêm thanh toán online hoặc quản lý đơn hàng nhưng chưa xác nhận rõ phạm vi');
    }

    if (customerMentionedLater) {
      if (contextIsBrandOrLogo) {
        parts.push('Khách muốn bổ sung tên thương hiệu/logo sau');
      } else {
        parts.push('Khách muốn bổ sung thêm thông tin sau');
      }
    }

    const budgetMatch = allCustomerTextForNote.match(/(\d+)\s*(tr|triệu|trieu)/i);
    if (budgetMatch) {
      parts.push(`Khách hỏi ngân sách khoảng ${budgetMatch[1]} triệu có làm được không`);
    }

    if (/giá|gia|bao nhiêu|bao nhieu|chi phí|chi phi|báo giá|bao gia|ngân sách|ngan sach/i.test(normalizedCustomerTextForNote)) {
      parts.push('Cần Sale xác nhận lại giá/báo giá');
    }

    if (/deadline|cuối tháng|cuoi thang|xong|hoàn thành|hoan thanh|bàn giao|ban giao/i.test(normalizedCustomerTextForNote)) {
      parts.push('Cần Sale xác nhận lại thời gian triển khai');
    }

    if (
      customerClearlySaidPayment ||
      customerClearlySaidOrderManagement ||
      customerClearlySaidBoth
    ) {
      parts.push('Cần Sale tư vấn thêm quy trình và phạm vi triển khai phù hợp');
    }

    return parts
      .filter(Boolean)
      .join('. ')
      .replace(/\.\s*\./g, '.')
      .trim() + '.';
  }

  function splitNoteSentences(note) {
    return String(note || '')
      .split('.')
      .map(s => s.trim())
      .filter(Boolean);
  }

  function mergeNotes(oldNote, newNote) {
    const oldIsUseful = !isGenericNote(oldNote) && !noteContainsBadGuess(oldNote);
    const newIsUseful = !isGenericNote(newNote) && !noteContainsBadGuess(newNote);

    if (oldIsUseful && !newIsUseful) {
      return oldNote;
    }

    if (!oldIsUseful && newIsUseful) {
      return newNote;
    }

    if (!oldIsUseful && !newIsUseful) {
      return newNote || oldNote || 'Chưa có';
    }

    const oldSentences = splitNoteSentences(oldNote);
    const newSentences = splitNoteSentences(newNote);

    const result = [];
    const seen = new Set();

    for (const sentence of [...oldSentences, ...newSentences]) {
      const key = normalizeNoteText(sentence)
        .replace(/[^a-z0-9\s]/g, '')
        .replace(/\s+/g, ' ')
        .trim();

      if (!key || seen.has(key)) continue;

      // Bỏ câu quá chung nếu đã có câu chi tiết hơn
      if (
        key === 'khach can tu van website' &&
        result.some(x => normalizeNoteText(x).includes('website ban'))
      ) {
        continue;
      }

      seen.add(key);
      result.push(sentence);
    }

    return result.slice(-5).join('. ') + '.';
  }

  let rebuiltNote = buildCleanNoteFromCustomerText();

  // Nếu khách đã chọn đặt hàng cơ bản trước, ghi chú phải ưu tiên đúng ý này
  if (customerChoseBasicOrderFirst) {
    cleanedAiNote =
      'Khách cần website bán mỹ phẩm có giỏ hàng. Khách muốn dùng tính năng đặt hàng cơ bản trước, chưa chọn thanh toán online/quản lý đơn hàng nâng cao. Cần tư vấn thêm cấu trúc sản phẩm và quy trình đặt hàng cơ bản.';
  } else {
    if (
      noteContainsBadGuess(cleanedAiNote) ||
      isGenericNote(cleanedAiNote)
    ) {
      cleanedAiNote = rebuiltNote;
    }

    // Nếu AI ghi chắc cả thanh toán online và quản lý đơn hàng chỉ vì khách nói "có ạ", viết lại cho an toàn
    if (
      customerSaidVagueYesForNote &&
      !customerClearlySaidBoth &&
      !customerClearlySaidPayment &&
      !customerClearlySaidOrderManagement &&
      /thanh toán online|thanh toan online/i.test(cleanedAiNote) &&
      /quản lý đơn hàng|quan ly don hang/i.test(cleanedAiNote)
    ) {
      cleanedAiNote = rebuiltNote;
    }

    // Ghép ghi chú cũ trong CRM với ghi chú mới, tránh mất chi tiết ban đầu
    cleanedAiNote = mergeNotes(existingAiNoteFromCrm, cleanedAiNote);

    // Nếu sau khi ghép vẫn quá chung, dùng bản dựng lại từ nhu cầu + tin nhắn
    if (isGenericNote(cleanedAiNote)) {
      cleanedAiNote = rebuiltNote;
    }
  }

  // Giới hạn độ dài ghi chú để Notion dễ đọc
  if (cleanedAiNote.length > 900) {
    cleanedAiNote = cleanedAiNote.slice(0, 900).trim();
  }

  parsedData.customer_ai_note = cleanedAiNote || 'Chưa có';

  return [{
    json: {
      customer_name: parsedData.customer_name,
      phone_number: parsedData.phone_number,
      need_summary: parsedData.need_summary,
      customer_ai_note: parsedData.customer_ai_note,
      reply_message: parsedData.reply_message,
      has_valid_phone: parsedData.has_valid_phone,
      handoff_needed: parsedData.handoff_needed,
      handoff_reason: parsedData.handoff_reason,
      should_notify_sale: shouldNotifySale
    }
  }];

} catch (error) {
  return [{
    json: {
      customer_name: 'Chưa có',
      phone_number: 'Chưa có',
      need_summary: 'Chưa có',
      customer_ai_note: 'Chưa có',
      has_valid_phone: false,
      handoff_needed: false,
      handoff_reason: 'Lỗi parse JSON',
      should_notify_sale: false,
      reply_message:
        'Dạ mình đang xử lý lại thông tin của bạn. Bạn cho mình biết thêm nhu cầu chính của website để mình tư vấn đúng hơn nhé.'
    }
  }];
}

